// Paginated pull of ALL conversations (follow meta.nextPageUrl), keep inbound replies.
const headers = { Authorization: 'Bearer pit-55ca3e17-3bb5-478c-871d-9ea10945d50d', Version: '2021-04-15' };
let url = 'https://services.leadconnectorhq.com/conversations/search?locationId=htgHvVfBZ1WH3UpQoxaa&limit=100&sortBy=last_message_date&sort=desc';
const out = [];
let pages = 0;
while (url && pages < 50) {
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
  const convs = (resp && resp.conversations) || [];
  for (const c of convs) {
    if (c.lastMessageDirection !== 'inbound') continue;
    const body = (c.lastMessageBody || '').trim();
    if (!body) continue;
    out.push({ json: { contactId: c.contactId, email: c.email || null, ts: c.lastMessageDate, body: body.slice(0, 2000) } });
  }
  url = (resp && resp.meta && resp.meta.nextPageUrl) ? resp.meta.nextPageUrl : null;
  pages++;
}
return out;

const meta = $('Fetch + extract replies (paged)').all();
const resps = $input.all();
function norm(t){ t=String(t||'').toLowerCase(); if(t.includes('opt'))return 'Opt-out'; if(t.includes('posit'))return 'Positive'; if(t.includes('negat'))return 'Negative'; return 'Neutral'; }
const replies = [];
for (let i=0;i<meta.length;i++){ let txt=''; try{ txt=resps[i].json.content[0].text; }catch(e){ txt=''; } replies.push({ contactId: meta[i].json.contactId, email: meta[i].json.email, sentiment: norm(txt), ts: meta[i].json.ts }); }
return [{ json: { replies } }];

// Paginated pull of ALL opportunities (contactId + status) for the handoff metric.
const headers = { Authorization: 'Bearer pit-55ca3e17-3bb5-478c-871d-9ea10945d50d', Version: '2021-07-28' };
let url = 'https://services.leadconnectorhq.com/opportunities/search?location_id=htgHvVfBZ1WH3UpQoxaa&limit=100';
const opportunities = [];
let pages = 0;
while (url && pages < 50) {
  const resp = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
  const opps = (resp && resp.opportunities) || [];
  for (const o of opps) opportunities.push({ contactId: o.contactId, status: o.status });
  url = (resp && resp.meta && resp.meta.nextPageUrl) ? resp.meta.nextPageUrl : null;
  pages++;
}
return [{ json: { opportunities } }];

const replies = $('Collect classified').first().json.replies || [];
const emails = [...new Set(replies.filter(r => r.sentiment === 'Positive' && r.email).map(r => String(r.email).trim()))];
const inList = emails.length ? emails.map(e => "'" + e.replace(/'/g, "\\'") + "'").join(',') : "''";
const soql = "SELECT Email, ConvertedOpportunity.StageName, ConvertedOpportunity.csbs__Commission_Amount__c FROM Lead WHERE IsConverted = true AND Email IN (" + inList + ")";
return [{ json: { soql, positiveEmails: emails.length } }];

const replies = $('Collect classified').first().json.replies || [];
const opps = ($('Fetch opportunities (paged)').first().json.opportunities) || [];
const won = new Set(opps.filter(o => o.status === 'won').map(o => o.contactId));

const counts = {};
for (const r of replies) {
  const d = new Date(Number(r.ts));
  const ym = d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0');
  const key = ym + '|' + r.sentiment;
  counts[key] = (counts[key] || 0) + 1;
}
const p_rows = Object.entries(counts).map(([k, v]) => { const [payout_month, sentiment] = k.split('|'); return { payout_month, sentiment, reply_count: v }; });

const posReplies = replies.filter(r => r.sentiment === 'Positive');
const posContacts = new Set(posReplies.map(r => r.contactId).filter(Boolean));
let advanced = 0;
for (const c of posContacts) if (won.has(c)) advanced++;

const sf = $input.all().map(i => i.json).filter(x => x && x.Email);
const fundedByEmail = {};
for (const row of sf) {
  const email = String(row.Email).toLowerCase();
  const opp = row.ConvertedOpportunity || {};
  if (opp.StageName === 'Funded') fundedByEmail[email] = (fundedByEmail[email] || 0) + Number(opp.csbs__Commission_Amount__c || 0);
}
const posEmails = [...new Set(posReplies.map(r => (r.email || '').toLowerCase()).filter(Boolean))];
let positive_funded = 0, funded_commission = 0;
for (const e of posEmails) if (fundedByEmail[e] !== undefined) { positive_funded++; funded_commission += fundedByEmail[e]; }
funded_commission = Math.round(funded_commission * 100) / 100;

return [{ json: { p_location: 'htgHvVfBZ1WH3UpQoxaa', p_rows, p_positive_replies: posContacts.size, p_positive_advanced: advanced, p_positive_funded: positive_funded, p_funded_commission: funded_commission } }];
